<!-- 图片轮播组件 -->
<template>
  <div class="image-carousel">
    <img :src="currentImage" alt="轮播图片" />
  </div>
</template>
  
  <script>
export default {
  props: {
    images: {
      type: Array,
      required: true
    }
  },
  data() {
    return {
      currentIndex: 0,
      currentImage: ''
    };
  },
  watch: {
    images: {
      immediate: true,
      handler(newVal) {
        if (newVal.length > 0) {
          this.currentImage = newVal[0];
        }
      }
    }
  },
  mounted() {
    this.startCarousel();
  },
  beforeDestroy() {
    clearInterval(this.timer);
  },
  methods: {
    startCarousel() {
      this.timer = setInterval(() => {
        this.currentIndex++;
        if (this.currentIndex >= this.images.length) {
          this.currentIndex = 0;
        }
        this.currentImage = this.images[this.currentIndex];
      }, 2000); // 这里设置轮播间隔为3秒，可按需调整
    }
  }
};
  </script>
  
  <style scoped>
.image-carousel {
  width: 100%; /* 可根据实际需求设置图片展示宽度等样式 */
  height: 100%;
  /* background-color: pink; */
}
