    async getMessage(oLiveView, type) {
      console.log("数据检查",oLiveView);
      // 拿到当前窗口分割状况，并且计算出有几个窗口，获取所有窗口中的参数，拿到szIP，这些是已经登陆并且已经在播放的录像机，这里可以直接进行播放操作而不用进行登陆操作。
      let num = this.selectedWndNum == 1 ? 1 : this.selectedWndNum == 2 ? 4 : this.selectedWndNum == 3 ? 9 : this.selectedWndNum == 4 ? 16 : 1
      let url = []
      for (let i = 0; i < num; i++) {
        let res = await window.WebVideoCtrl.I_GetWindowStatus(i)
        // console.log(res);
        if (res != null) {
          url.push(res.szIP)
        }
      }
      this.urlArr = [...new Set(url)];
      // console.log(this.urlArr);

      // 检查当前点击的设备有没有登陆
      let res = this.urlArr.find(v => v == oLiveView.szIP);
      console.log("res======================", res);
      if (res == undefined) {//说明此时应该登陆
        this.clickLoginOnly(oLiveView)
        if (type == 'real') {
          // this.clickLogin(oLiveView)
          // this.clickLoginOnly(oLiveView)
          setTimeout(()=>{
            this.clickStartRealPlay(oLiveView)
          },1000)
        } else {
          // this.clickLoginBack(oLiveView)
          setTimeout(()=>{
            this.clickLoginBack(oLiveView)
          },1000)
        }
      } else {
        if (type == 'real') {
          this.clickStartRealPlay(oLiveView)
        } else {
        // this.clickLoginOnly(oLiveView)
        console.log(oLiveView)
          this.clickStartPlayback(oLiveView)
        }
      }
