          });
          window.WebVideoCtrl.I_StartPlayback(szDeviceIdentify, {
            iRtspPort: iRtspPort,
            iStreamType: iStreamType,
            iChannelID: iChannelID,
            szStartTime: szStartTime,
            szEndTime: szEndTime,
            success: function () {
              szInfo = "开始回放成功！";
              console.log(szInfo);
              // showOPInfo(szDeviceIdentify + " " + szInfo);
            },
            error: function (oError) {
              szInfo = "开始回放失败！";
              console.log(szInfo);
              // showOPInfo(szDeviceIdentify + szInfo, oError.errorCode, oError.errorMsg);
            }
          });
        }
      }catch(status){
          console.log(status);
        if (403 === status) {
          console.log('设备不支持Websocket取流！');
        } else {
          console.log(status+'预览失败！-');
