            <template slot-scope="scope">
              {{ (Number(Number(pagenumber)-1)*Number(pagesize))+scope.$index + 1 }}
            </template>
          </el-table-column>
          <el-table-column prop="mine_name" label="单位名称" key="1" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="equipment_name" label="报警设备" key="2" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id == 3" key="3" prop="result_count_time" label="开始时间" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id == 3" key="4" prop="res_time" label="结束时间" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id != 3" key="5" prop="res_time" label="报警时间" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="conf_name" label="解析类型" key="6" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id != 3" key="7" prop="res_type" label="报警等级" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="warning_message" key="8" label="报警信息" width="200" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="system == 'UWB'" key="9" prop="uwb_id" label="标识卡" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id == 3" key="10" prop="Entering_num" label="进入数量" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column v-if="queryParams.template_type_id == 3" key="11" prop="Exiting_num" label="离开数量" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="approval_status" label="审批状态" key="12" :show-overflow-tooltip="true">
            <template slot-scope="scope">
              <span v-if="scope.row.approval_status == 0">正常</span>
              <span v-if="scope.row.approval_status == 1">误报</span>
            </template>
          </el-table-column>
          <el-table-column prop="disposal_time" label="审核时间" key="13" :show-overflow-tooltip="true"></el-table-column>
