            <template slot-scope="scope">
              <span v-if="scope.row.disposal_status == 0" style="color:red;">待处理</span>
              <span v-if="scope.row.disposal_status == 1">处理中</span>
              <span v-if="scope.row.disposal_status == 2" style="color:green;">已处理</span>
            </template>
          </el-table-column>
          <el-table-column key="15" label="报警图片" width="150px" align="center">
            <template slot-scope="scope">
              <div 
                class="image-carousel" 
                v-if="getImageList(scope.row).length > 1"
                @mouseenter="pauseCarousel(scope.row._carousel_key)" 
                @mouseleave="resumeCarousel(scope.row._carousel_key)"
              >
                <img 
                  :src="getCurrentImage(scope.row)" 
                  style="width: 120px; height: 60px; cursor: pointer; object-fit: cover;" 
                  alt=""
                  @click="handleLookImg(scope.row)"
                />
                <div class="carousel-indicator">
                  <span 
                    class="dot" 
                    v-for="(img, idx) in getImageList(scope.row)" 
                    :key="idx" 
                    :class="{ active: idx === getCurrentIndex(scope.row) }"
                    @click.stop="goToImage(scope.row, idx)"
                  ></span>
                </div>
                <div class="carousel-arrow">
                  <span class="arrow-left" @click.stop="prevImage(scope.row)">‹</span>
                  <span class="arrow-right" @click.stop="nextImage(scope.row)">›</span>
                </div>
              </div>
              <img 
                v-else-if="getImageList(scope.row).length === 1"
                :src="getImageList(scope.row)[0]" 
                style="width: 120px; height: 60px; cursor: pointer; object-fit: cover;" 
                alt=""
                @click="handleLookImg(scope.row)"
              />
              <span v-else style="color: #999; font-size: 12px;">未检出人脸</span>
            </template>
          </el-table-column>
          <el-table-column v-if="queryParams.template_type_id != 3 && $store.state.user_role_id == 1" key="16" label="无标注框报警图片" width="150px" align="center">
