              <div 
                class="image-carousel" 
                v-if="getImageList2(scope.row).length > 1"
                @mouseenter="pauseCarousel(scope.row._carousel_key2)" 
                @mouseleave="resumeCarousel2(scope.row._carousel_key2)"
              >
                <img 
                  :src="getCurrentImage2(scope.row)" 
                  style="width: 120px; height: 60px; cursor: pointer; object-fit: cover;" 
                  alt=""
                  @click="handleLookImg2(scope.row)"
                />
                <div class="carousel-indicator">
                  <span 
                    class="dot" 
                    v-for="(img, idx) in getImageList2(scope.row)" 
                    :key="idx" 
                    :class="{ active: idx === getCurrentIndex2(scope.row) }"
                    @click.stop="goToImage2(scope.row, idx)"
                  ></span>
                </div>
