      width="70%"
      :before-close="handleClosePictureOpen"
      class="image-dialog"
    >
      <div slot="title" class="dialog-title">
        <span class="title-main">{{ currentDialogRow ? currentDialogRow.conf_name || '' : '' }}</span>
        <span class="title-sub">{{ currentDialogRow ? currentDialogRow.equipment_name || '' : '' }}</span>
        <span class="title-type">{{ currentDialogRow ? currentDialogRow.res_type || '' : '' }}</span>
        <!-- <span class="title-time">{{ currentDialogRow ? currentDialogRow.res_time || '' : '' }}</span> -->
      </div>
      
