            @click="handleDialogPauseToggle"
          />
          
          <div class="dialog-carousel-indicator" v-if="currentDialogImageList.length > 1">
            <span 
              class="dot" 
              v-for="(img, idx) in currentDialogImageList" 
              :key="idx" 
              :class="{ active: idx === currentDialogImageIndex }"
              @click.stop="goToDialogImage(idx)"
            ></span>
          </div>
          
          <div class="dialog-carousel-arrow" v-if="currentDialogImageList.length > 1">
            <span class="arrow-left" @click.stop="handleDialogPrevImage">‹</span>
            <span class="arrow-right" @click.stop="handleDialogNextImage">›</span>
          </div>
        </div>
        
        <!-- 上一条/下一条按钮 -->
        <div class="dialog-nav">
          <el-button 
            class="nav-btn prev-btn"
            :disabled="currentDialogDataIndex <= 0"
            @click="handlePrevData"
          >
            <i class="el-icon-arrow-left"></i> 上一条
          </el-button>
          <!-- <span class="data-counter">{{ currentDialogDataIndex + 1 }} / {{ dialogFilteredData.length }}</span> -->
          <el-button 
            class="nav-btn next-btn"
            type="primary"
            :disabled="currentDialogDataIndex >= dialogFilteredData.length - 1"
            @click="handleNextData"
          >
            下一条 <i class="el-icon-arrow-right"></i>
          </el-button>
        </div>
      </div>
    </el-dialog>
    
