              </div>
              <img 
                v-else-if="getImageList(scope.row).length === 1"
                :src="getImageList(scope.row)[0]" 
                style="width: 120px; height: 60px; cursor: pointer; object-fit: cover;" 
                alt=""
                @click="handleLookImg(scope.row)"
              />
              <span v-else style="color: #999; font-size: 12px;">暂无图片</span>
            </template>
          </el-table-column>
          <el-table-column label="报警详情" class-name="jia_btn_class">
            <template slot-scope="scope">
              <el-button type="text" icon="el-icon-video-camera" size="mini" @click="handleOpenSpfx(scope.row,4)" v-if="queryParams.template_type_id == 3">视频分析回放</el-button>
              <el-button type="text" icon="el-icon-video-camera" size="mini" @click="handleOpenSpfx(scope.row,1)" v-else>视频分析回放</el-button>
              <el-button type="text" icon="el-icon-video-camera" size="mini" @click="handleOpenSpfx(scope.row,0)">报警回放</el-button>
            </template>
          </el-table-column>
        </el-table>
        <br />
        <el-pagination @current-change="handleCurrentChange" @size-change="handleSizeChange" :current-page="pagenumber" :page-size="pagesize" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="pagelength" style="float: right;">
        </el-pagination>
        <br />
      </div>
    </el-dialog>

    <el-dialog title="处置" :visible.sync="dialogFormVisible_cz">
      <div class="box">
        <div class="left">
          <div 
            class="image-carousel imgbox" 
            v-if="getImageList(formcz).length > 1"
            @mouseenter="pauseCarousel(formcz._carousel_key || 'cz')" 
            @mouseleave="resumeCarousel(formcz._carousel_key || 'cz')"
          >
            <img 
              :src="getCurrentImage(formcz)" 
              style="width: 100%; object-fit: contain;" 
              alt=""
            />
            <div class="carousel-indicator" style="bottom: 4px;">
              <span 
                class="dot" 
                v-for="(img, idx) in getImageList(formcz)" 
                :key="idx" 
                :class="{ active: idx === getCurrentIndex(formcz) }"
                @click.stop="goToImage(formcz, idx)"
              ></span>
            </div>
          </div>
          <img 
            v-else-if="getImageList(formcz).length === 1"
            :src="getImageList(formcz)[0]" 
            style="width: 100%;object-fit: contain;" 
            alt=""
          />
          <div v-else style="width: 100%; height: 200px; display: flex; align-items: center; justify-content: center; background: #f5f7fa; color: #999;">
            暂无图片
          </div>
        </div>
        <div class="right">
          <el-form :model="formcz">
            <el-form-item label="审批状态" :label-width="formLabelWidth">
              <el-select v-model="formcz.approval_status" style="width: 100%;" placeholder="审批状态">
                <el-option label="正常" value="0"></el-option>
                <el-option label="误报" value="1"></el-option>
              </el-select>
            </el-form-item>
            <el-form-item label="处置状态" :label-width="formLabelWidth">
              <el-select v-model="formcz.disposal_status" style="width: 100%;" placeholder="处置状态">
                <el-option label="待处理" value="0"></el-option>
                <el-option label="处理中" value="1"></el-option>
                <el-option label="已处理" value="2"></el-option>
              </el-select>
            </el-form-item>
            <el-form-item label="审批意见" :label-width="formLabelWidth">
              <el-input v-model="formcz.approval_opinion" style="width: 100%;" type="textarea" :rows="2" placeholder="请输入审批意见"></el-input>
            </el-form-item>
            <el-form-item label="处置措施" :label-width="formLabelWidth">
              <el-input v-model="formcz.disposal_opinion" style="width: 100%;" type="textarea" :rows="2" placeholder="请输入处置措施"></el-input>
            </el-form-item>
            <el-form-item label="处置时间" :label-width="formLabelWidth">
              <el-date-picker
                v-model="formcz.disposal_time"
                type="datetime"
                :picker-options="pickerOptions"
                value-format="yyyy-MM-dd HH:mm:ss"
                style="width: 100%;"
                placeholder="选择日期时间">
              </el-date-picker>
            </el-form-item>
          </el-form>
        </div>
      </div>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible_cz = false">取 消</el-button>
        <el-button type="primary" @click="sure()">确 定</el-button>
      </div>
    </el-dialog>
    <div class="bj_list" v-if="loading_bj && this.bjobj.length>0">
      <el-card class="box-card" style="height: 100%;">
        <div slot="header" class="clearfix">
          <span>报警信息</span>
          <el-button icon="el-icon-close" style="float: right; padding: 3px 0" type="text" @click="closefn"></el-button>
        </div>
        <div style="width:300px;height: 150px;background: #ccc;margin: 0 auto;margin-top: 12px;">
          <img style="width: 100%;height: 100%;background-size: 100% 100%;" :src="bj_forms.carousel_images" alt="">
        </div>
        <div class="bjitems">
          处置状态: 
          <span v-if="bj_forms.disposal_status*1 == 0" style="color:red;">待处理</span>
          <span v-if="bj_forms.disposal_status*1 == 1">处理中</span>
          <span v-if="bj_forms.disposal_status*1 == 2" style="color:green;">已处理</span>
        </div>
        <div class="bjitems">
          报警类型: <span>{{ bj_forms.algorithm_name }}</span>
        </div>
        <div class="bjitems">
          报警等级: <span>{{ bj_forms.res_type }}</span>
        </div>
        <div class="bjitems">
          报警地点: <span>{{ bj_forms.equipment_name }}</span>
        </div>
        <div class="bjitems">
          报警时间: <span>{{ bj_forms.res_time }}</span>
        </div>
        <div class="bjitems">
          处理时间: <span>{{ bj_forms.disposal_time }}</span>
        </div>
        
        <div class="bjitems_b">
          <el-button size="small" @click="lastfn" v-show="this.bjobj.length>1">上一条</el-button>
          <el-button size="small" type="primary" @click="czfn(bj_forms)">处置报警</el-button>
          <el-button size="small" @click="nextfn" v-show="this.bjobj.length>1">下一条</el-button>
        </div>
      </el-card>
    </div>
  </div>
</template>

<script>
import { MessageBox } from "element-ui"
import images_loop from "./component/images_loop.vue";
import carousel from "./component/carousel.vue";
import carousel2 from "./component/carousel copy.vue";
import axios from "axios";
import flvjs from 'flv.js';
import { spfxApi } from '@/api/spfx.js';
import { dictApi } from '@/api/system/dict.js';
import { modelApi } from '@/api/model/index';
import { hkvsApi } from "@/api/hkvs/index";
import { bjlbApi } from "@/api/bjlb";
import HKVS from "./HK/hkvideo/new/oldVideo.vue"
import JSZip from 'jszip';

export default {
  name: "bjlb",
  components: {
    images_loop,
    carousel,
    carousel2,
    HKVS,
  },
  data() {
    return {
      timer:null,
      loading_bj: false,
      bjobj:[],
      bj_index: 0,
      bj_forms:{},
      czzt: [
        { "id": "0", "value": "待处理"},
        { "id": "1", "value": "处理中"},
        { "id": "2", "value": "已处理"},
      ],
      spzt: [
        { "id": "0", "value": "正常"},
        { "id": "1", "value": "误报"},
      ],
      formLabelWidth: '100px',
      dialogFormVisible_cz: false,
      formcz:{
        approval_status: '',
        disposal_status: '',
        approval_opinion: '',
        disposal_opinion: '',
        disposal_time: '',
      },
      system: window.wgParameter.system,
      clickType:'',
      StartTime: "",
      EndTime: "",
      mkname: "",
      jkdname: "",
      bjtype: "",
      algorithm_id: "",
      Algorithm_config_id: "",
      queryParams: {
        template_type_id: '',
        algorithm_id: '',
        disposal_status: '',
        approval_status: '',
      },
      options1: [],
      options2: [],
      options3: [],
      options4: [],
      options5: [],
      props: {
        checkStrictly: false,
        emitPath: false,
        value: "id",
        label: "equipment_name",
      },
      loading: false,
      tableData: [],
      tableDataAll: [],
      currentPage: 1,
      pagenumber: 1,
      pagesize: 15,
      pagelength: 0,
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      imgTitle: "",
      imgOpen: false,
      imgData: {},
      video_page_id: null,
      dialogVisibleBox: false,
      excelName: "报警列表",
      column: [
        {
          title: "序号",
          key: "index",
          type: "text",
        },
        {
          title: "单位名称",
          key: "mine_name",
          type: "text",
        },
        {
          title: "报警设备",
          key: "equipment_name",
          type: "text",
        },
        {
          title: "时间",
          key: "res_time",
          type: "text",
        },
        {
          title: "算法",
          key: "algorithm_name",
          type: "text",
        },
        {
          title: "算法名称",
          key: "conf_name",
          type: "text",
        },
        {
          title: "报警等级",
          key: "res_type",
          type: "text",
        },
        {
          title: "报警图片",
          key: "res_image",
          type: "image",
          width: 100,
          height: 50,
        },
      ],
      pickerOptions: {
        disabledDate(time) {
          const today = new Date();
          today.setHours(0, 0, 0, 0);
          const oneMonthAgo = new Date(today);
          oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);
          oneMonthAgo.setHours(0, 0, 0, 0);
          return time.getTime() > today.getTime() || time.getTime() < oneMonthAgo.getTime();
        },
        disabledTime(time) {
          if (!this.StartTime) return false;
          try {
            const startTime = new Date(this.StartTime);
            if (isNaN(startTime.getTime())) throw new Error('Invalid date format');
            return time.getTime() < startTime.getTime();
          } catch (e) {
            console.error('Error parsing StartTime:', e);
            return false;
          }
        },
      },
      alarmVideoOpen: false,
      alarmVideoTitle: '',
      interTime: null,
      pictureTitle: '',
      pictureOpen: false,
      pictureArr: [],
      pictureArrId: 0,
      modelTypeDict: [],
      modelTypeOptions: [],
      HKVSTitle: '',
      HKVSOpen: false,
      ssfxVideo: '/static/img/video/AIspfx.mp4',
      ssfxVideoFlv: '',
      flvPlayer: null,
      bjlbOpen: false,
      multipleSelection: [],
      
      // ========== 轮播相关数据 ==========
      rowCarouselIndex: {},
      rowCarouselTimer: {},
      rowCarouselIndex2: {},
      rowCarouselTimer2: {},
      carouselInterval: 3000,
      
      // 弹窗轮播相关
      dialogCarouselTimer: null,
      dialogPaused: false,
      currentDialogRow: null,
      currentDialogImageList: [],
      currentDialogImageIndex: 0,
      currentDialogDataIndex: 0,
      dialogFilteredData: [],
      currentDialogType: '', // 'carousel' 或 'ori'
    };
  },
  watch: {
    StartTime(newVal, oldVal) {
      this.validateTimeRange();
    },
    EndTime(newVal, oldVal) {
      this.validateTimeRange();
    },
    tableData: {
      handler(newVal) {
        if (newVal && newVal.length > 0) {
          this.$nextTick(() => {
            this.initRowCarousel();
            this.initRowCarousel2();
          });
        }
      },
      deep: true
    }
  },
  methods: {
    // ========== 图片解析方法 ==========
    getImageList(row) {
      if (!row) return [];
      let imageList = row.carousel_images_list || '';
      if (Array.isArray(imageList)) {
        return imageList.filter(url => url && url.trim());
      }
      if (typeof imageList === 'string') {
        try {
          const jsonStr = imageList.replace(/'/g, '"');
          const parsed = JSON.parse(jsonStr);
          if (Array.isArray(parsed)) {
            return parsed.filter(url => url && url.trim());
          }
        } catch (e) {
          return [];
        }
      }
      return [];
    },
    
    getImageList2(row) {
      if (!row) return [];
      let imageList = row.ori_images_list || '';
      if (Array.isArray(imageList)) {
        return imageList.filter(url => url && url.trim());
      }
      if (typeof imageList === 'string') {
        try {
          const jsonStr = imageList.replace(/'/g, '"');
          const parsed = JSON.parse(jsonStr);
          if (Array.isArray(parsed)) {
            return parsed.filter(url => url && url.trim());
          }
        } catch (e) {
          return [];
        }
      }
      return [];
    },
    
    // ========== 第一组轮播方法（carousel_images_list） ==========
    getCurrentImage(row) {
      const images = this.getImageList(row);
      if (images.length === 0) return '';
      const key = row._carousel_key || row.Algorithm_result_id || row.id;
      const index = this.rowCarouselIndex[key] || 0;
      return images[index % images.length];
    },
    
    getCurrentIndex(row) {
      const key = row._carousel_key || row.Algorithm_result_id || row.id;
      return this.rowCarouselIndex[key] || 0;
    },
    
    nextImage(row) {
      const images = this.getImageList(row);
      if (images.length <= 1) return;
      const key = row._carousel_key || row.Algorithm_result_id || row.id;
      if (!this.rowCarouselIndex[key]) {
        this.$set(this.rowCarouselIndex, key, 0);
      }
      this.rowCarouselIndex[key] = (this.rowCarouselIndex[key] + 1) % images.length;
      this.$forceUpdate();
    },
    
    prevImage(row) {
      const images = this.getImageList(row);
      if (images.length <= 1) return;
      const key = row._carousel_key || row.Algorithm_result_id || row.id;
      if (!this.rowCarouselIndex[key]) {
        this.$set(this.rowCarouselIndex, key, 0);
      }
      this.rowCarouselIndex[key] = (this.rowCarouselIndex[key] - 1 + images.length) % images.length;
      this.$forceUpdate();
    },
    
    goToImage(row, index) {
      const images = this.getImageList(row);
      const key = row._carousel_key || row.Algorithm_result_id || row.id;
      if (index >= 0 && index < images.length) {
        this.$set(this.rowCarouselIndex, key, index);
        this.$forceUpdate();
      }
    },
    
    pauseCarousel(key) {
      if (this.rowCarouselTimer[key]) {
        clearInterval(this.rowCarouselTimer[key]);
        this.rowCarouselTimer[key] = null;
      }
    },
    
    resumeCarousel(key) {
      const row = this.tableData.find(item => {
        const itemKey = item._carousel_key || item.Algorithm_result_id || item.id;
        return itemKey === key;
      });
      if (!row) return;
      const images = this.getImageList(row);
      if (images.length <= 1) return;
      
      if (this.rowCarouselTimer[key]) {
        clearInterval(this.rowCarouselTimer[key]);
        this.rowCarouselTimer[key] = null;
      }
      
      this.rowCarouselTimer[key] = setInterval(() => {
        this.nextImage(row);
      }, this.carouselInterval);
    },
    
    initRowCarousel() {
      Object.keys(this.rowCarouselTimer).forEach(key => {
        if (this.rowCarouselTimer[key]) {
          clearInterval(this.rowCarouselTimer[key]);
          this.rowCarouselTimer[key] = null;
        }
      });
      this.rowCarouselIndex = {};
      
      this.tableData.forEach((row) => {
        const key = row._carousel_key || row.Algorithm_result_id || row.id || `row_${Math.random()}`;
        row._carousel_key = key;
        const images = this.getImageList(row);
        if (images.length > 1) {
          this.$set(this.rowCarouselIndex, key, 0);
          this.rowCarouselTimer[key] = setInterval(() => {
            this.nextImage(row);
          }, this.carouselInterval);
        } else if (images.length === 1) {
          this.$set(this.rowCarouselIndex, key, 0);
        }
      });
    },
    
    // ========== 第二组轮播方法（ori_images_list） ==========
    getCurrentImage2(row) {
      const images = this.getImageList2(row);
      if (images.length === 0) return '';
      const key = row._carousel_key2 || row.Algorithm_result_id || row.id;
      const index = this.rowCarouselIndex2[key] || 0;
      return images[index % images.length];
    },
    
    getCurrentIndex2(row) {
      const key = row._carousel_key2 || row.Algorithm_result_id || row.id;
      return this.rowCarouselIndex2[key] || 0;
    },
    
    nextImage2(row) {
      const images = this.getImageList2(row);
      if (images.length <= 1) return;
      const key = row._carousel_key2 || row.Algorithm_result_id || row.id;
      if (!this.rowCarouselIndex2[key]) {
        this.$set(this.rowCarouselIndex2, key, 0);
      }
      this.rowCarouselIndex2[key] = (this.rowCarouselIndex2[key] + 1) % images.length;
      this.$forceUpdate();
    },
    
    prevImage2(row) {
      const images = this.getImageList2(row);
      if (images.length <= 1) return;
      const key = row._carousel_key2 || row.Algorithm_result_id || row.id;
      if (!this.rowCarouselIndex2[key]) {
        this.$set(this.rowCarouselIndex2, key, 0);
      }
      this.rowCarouselIndex2[key] = (this.rowCarouselIndex2[key] - 1 + images.length) % images.length;
      this.$forceUpdate();
    },
    
    goToImage2(row, index) {
      const images = this.getImageList2(row);
      const key = row._carousel_key2 || row.Algorithm_result_id || row.id;
      if (index >= 0 && index < images.length) {
        this.$set(this.rowCarouselIndex2, key, index);
        this.$forceUpdate();
      }
    },
    
    pauseCarousel2(key) {
      if (this.rowCarouselTimer2[key]) {
        clearInterval(this.rowCarouselTimer2[key]);
        this.rowCarouselTimer2[key] = null;
      }
    },
    
    resumeCarousel2(key) {
      const row = this.tableData.find(item => {
        const itemKey = item._carousel_key2 || item.Algorithm_result_id || item.id;
        return itemKey === key;
      });
      if (!row) return;
      const images = this.getImageList2(row);
      if (images.length <= 1) return;
      
      if (this.rowCarouselTimer2[key]) {
        clearInterval(this.rowCarouselTimer2[key]);
        this.rowCarouselTimer2[key] = null;
      }
      
      this.rowCarouselTimer2[key] = setInterval(() => {
        this.nextImage2(row);
      }, this.carouselInterval);
    },
    
    initRowCarousel2() {
      Object.keys(this.rowCarouselTimer2).forEach(key => {
        if (this.rowCarouselTimer2[key]) {
          clearInterval(this.rowCarouselTimer2[key]);
          this.rowCarouselTimer2[key] = null;
        }
      });
      this.rowCarouselIndex2 = {};
      
      this.tableData.forEach((row) => {
        const key = row._carousel_key2 || row.Algorithm_result_id || row.id || `row2_${Math.random()}`;
        row._carousel_key2 = key;
        const images = this.getImageList2(row);
        if (images.length > 1) {
          this.$set(this.rowCarouselIndex2, key, 0);
          this.rowCarouselTimer2[key] = setInterval(() => {
            this.nextImage2(row);
          }, this.carouselInterval);
        } else if (images.length === 1) {
          this.$set(this.rowCarouselIndex2, key, 0);
        }
      });
    },
    
    // ========== 弹窗轮播方法 ==========
    clearDialogCarousel() {
      if (this.dialogCarouselTimer) {
        clearInterval(this.dialogCarouselTimer);
        this.dialogCarouselTimer = null;
      }
    },
    
    startDialogCarousel() {
      this.clearDialogCarousel();
      if (this.currentDialogImageList.length > 1 && !this.dialogPaused) {
        this.dialogCarouselTimer = setInterval(() => {
          this.currentDialogImageIndex = (this.currentDialogImageIndex + 1) % this.currentDialogImageList.length;
        }, this.carouselInterval);
      }
    },
    
    handleDialogPauseToggle() {
      this.dialogPaused = !this.dialogPaused;
      if (this.dialogPaused) {
        this.clearDialogCarousel();
      } else {
        this.startDialogCarousel();
      }
    },
    
    handleDialogPrevImage() {
      if (this.currentDialogImageIndex > 0) {
        this.currentDialogImageIndex--;
        this.startDialogCarousel();
      }
    },
    
    handleDialogNextImage() {
      if (this.currentDialogImageIndex < this.currentDialogImageList.length - 1) {
        this.currentDialogImageIndex++;
        this.startDialogCarousel();
      }
    },
    
    goToDialogImage(index) {
      if (index >= 0 && index < this.currentDialogImageList.length) {
        this.currentDialogImageIndex = index;
        this.startDialogCarousel();
      }
    },
    
    // ========== 查看图片 - 打开弹窗 ==========
    handleLookImg(row) {
      const images = this.getImageList(row);
      if (images.length === 0) {
        this.$message.warning('该记录没有图片');
        return;
      }
      
      this.currentDialogType = 'carousel';
      this.openPictureDialog(row, images);
    },
    
    handleLookImg2(row) {
      const images = this.getImageList2(row);
      if (images.length === 0) {
        this.$message.warning('该记录没有图片');
        return;
      }
      
      this.currentDialogType = 'ori';
      this.openPictureDialog(row, images);
    },
    
    openPictureDialog(row, images) {
      // 过滤出所有有图片的数据行
      this.dialogFilteredData = [];
      this.tableData.forEach((item) => {
        const imgList = this.currentDialogType === 'carousel' ? this.getImageList(item) : this.getImageList2(item);
        if (imgList.length > 0) {
          this.dialogFilteredData.push(item);
        }
      });
      
      if (this.dialogFilteredData.length === 0) {
        this.$message.warning('当前页没有可查看的图片');
        return;
      }
      
      // 查找当前行在过滤数据中的索引
      const targetKey = row._carousel_key || row._carousel_key2 || row.Algorithm_result_id || row.id;
      let targetIndex = this.dialogFilteredData.findIndex(item => {
        const itemKey = item._carousel_key || item._carousel_key2 || item.Algorithm_result_id || item.id;
        return itemKey === targetKey || item.Algorithm_result_id === row.Algorithm_result_id;
      });
      
      if (targetIndex === -1) targetIndex = 0;
      
      this.currentDialogDataIndex = targetIndex;
      this.dialogPaused = false;
      
      // 更新弹窗数据
      const data = this.dialogFilteredData[this.currentDialogDataIndex];
      if (data) {
        const imgList = this.currentDialogType === 'carousel' ? this.getImageList(data) : this.getImageList2(data);
        this.currentDialogRow = data;
        this.currentDialogImageList = imgList;
        this.currentDialogImageIndex = 0;
        this.pictureOpen = true;
        this.startDialogCarousel();
      }
    },
    
    handlePrevData() {
      if (this.currentDialogDataIndex > 0) {
        this.currentDialogDataIndex--;
        this.dialogPaused = false;
        const data = this.dialogFilteredData[this.currentDialogDataIndex];
        if (data) {
          const imgList = this.currentDialogType === 'carousel' ? this.getImageList(data) : this.getImageList2(data);
